    description: "猞猁体长 0.8–1.3 米，尾仅 10–25 cm，体重 12–30 kg，是猞猁属中体型最大者。它四肢粗长、脚掌宽大，像天然的雪地靴；耳尖生有黑色簇毛，脸颊两侧垂下长毛，被毛为灰黄至红棕色，散布暗色斑点，尾短而末端发黑。\n\n猞猁栖息于北半球亚欧大陆的针叶林、混交林和苔原森林，尤其喜欢岩石多、灌木密的山地。它主食狍、麝、雪兔等，常埋伏于兽径旁或树上，短距离突袭，冬季也会循脚印长途追踪。它多在黄昏和夜间单独活动，领地范围可达数百平方千米，用尿液、粪便和抓痕标记。每年 2–4 月发情，妊娠期约 70 天，每胎 2–4 仔。在中国，猞猁分布于东北、华北和西南山区，野生种群稀少。",
