    description: "猕猴体长 0.4–0.6 米，尾长 0.2–0.3 米，体重 4–8 kg，雄性大于雌性。它的毛色为棕灰至黄褐色，面部裸露呈粉红色，臀部有红色胼胝；口腔两侧有颊囊，可把食物暂存其中带回安全处慢慢咀嚼。\n\n猕猴分布于南亚、东南亚和东亚的森林、灌丛、农田乃至城市边缘，是分布最广的灵长类之一，食谱包括果实、嫩叶、种子、昆虫和小型动物。它们结成 10–50 只的群体，社会等级严格，个体通过理毛建立联盟；雌性终生留在出生的群中，雄性成年后迁往其他群。猕猴每年繁殖一次，妊娠期约 165 天，每胎 1 仔。由于适应力强且与人类活动区域重叠，猕猴常因取食农作物与人类发生冲突，部分地区还需控制种群数量。",
    habitat: "森林、灌丛、农田和城市边缘，从平原到海拔 3000 米的山地",
