    description: "环尾狐猴体长 0.4–0.5 米，尾长 0.5–0.6 米，体重 2–2.5 kg。它的背部为灰褐色，腹部白色，面部有黑色眼斑和白色面纹；尾巴上有 13–15 个黑白相间的环纹，末端总是黑色，行走时常高高竖起，像一面旗帜。\n\n环尾狐猴仅分布于马达加斯加岛南部的干旱多刺林与河岸森林，主食果实、树叶、花和少量昆虫，旱季会取食仙人掌类植物补充水分。它们结成 6–25 只的群体，雌性在群体中占据支配地位，雄性通过腕部腺体的气味标记划分领地。清晨，它们常坐在岩石上张开四肢晒太阳，被称为“太阳崇拜”行为。每年 4–5 月繁殖，妊娠期约 135 天，每胎 1–2 仔。由于森林砍伐和干旱加剧，环尾狐猴被列为濒危。",
