    description: "虎鲸体长 5–9.8 米，体重 3–9 吨，雄性明显大于雌性。它的身体黑白分明，眼后有一块白色椭圆斑，背鳍高而直立，雄性背鳍可达 1.8 米；腹部和尾柄下方为白色，尾鳍宽大有力。\n\n虎鲸分布于世界各大洋，从极地到热带都能见到，常出现在近岸和冰缘海域。它们是高度社会化的动物，以母系群为核心，由最年长的雌性带领，成员包括其子女和孙辈；不同种群有各自独特的叫声“方言”，并有稳定的食性偏好：有的专吃鱼类，有的捕食海豹、海狮甚至大型鲸类的幼崽。虎鲸会用尾鳍拍打水面，制造波浪把浮冰上的海豹冲落水中。雌鲸妊娠期约 15–18 个月，每胎 1 仔。目前全球数量尚可，但部分地方种群受食物减少和污染影响。",
