    description: "蓝鲸体长 24–30 米，最长记录超过 33 米，体重可达 150 吨以上，雌性大于雄性，是地球现存最大的动物。它的身体呈细长的纺锤形，背部蓝灰色带有斑驳浅斑，腹部有 60–90 条纵向褶沟，喷气水柱可高达 9–12 米。\n\n蓝鲸分布于全球各大洋，从极地到热带都有记录，但更偏好冷水海域，常在南极、北太平洋和北大西洋的富营养水域觅食。它几乎只吃磷虾，夏季每天可吞食 2–4 吨；捕食时张口冲入虾群，用鲸须滤下食物，再把海水挤出。蓝鲸的叫声低沉，频率低于人类听觉下限，可在海水中传播数百公里。雌鲸妊娠期约 10–12 个月，每胎 1 仔，幼鲸每天可增重约 90 kg。20 世纪的大规模捕鲸使其数量锐减，如今仍属濒危。",
