    description: "北极熊体长 1.8–2.5 米（雄性可近 3 米），肩高 1.2–1.6 米，雄性体重 350–700 kg，雌性约 150–300 kg。它的毛发看似白色，实际上中空而透明，皮肤是黑色的，有助于吸收阳光热量；脚掌宽大并长有毛，可在冰面上防滑。\n\n北极熊分布在北极海冰覆盖的环极地区，活动范围可达数十万平方千米，主要捕食环斑海豹，常在冰面呼吸孔旁守候，用前掌猛击将海豹拖上冰面。它能在海水中连续游泳数十公里，嗅觉可在数公里外察觉海豹的气息。北极熊并不冬眠，只有怀孕的雌熊会在雪洞中越冬并产仔，妊娠期约 8 个月，每胎 1–3 仔。海冰减少缩短了捕猎时间与平台，使部分种群数量下降，长期生存面临威胁。",
