    description: "红大袋鼠体长 0.75–1.6 米，尾长 0.65–1.2 米，雄性体重 55–85 kg，雌性 18–40 kg，是现存最大的有袋类。雄性体色偏红褐，雌性偏蓝灰；前肢短小，后肢修长有力，尾巴粗壮，可支撑身体或跳跃时保持平衡。\n\n红大袋鼠栖息于澳大利亚内陆的干旱草原、灌丛和荒漠，食物主要是草类和灌木嫩叶，可在缺水环境下依靠植物中的水分生活。它们结成 10 只左右的松散群体，黄昏后活动；跳跃时可双脚同时蹬地，时速可达 60 km/h 以上，单次跳跃可跨越 8 米。雌袋鼠有胚胎滞育能力，环境恶劣时延缓胚胎发育；幼仔出生时仅约 1 克，需爬进育儿袋继续发育约半年。作为澳大利亚的标志性动物，红大袋鼠种群总体稳定，但局部受干旱与人类活动影响。",
