    description: "美洲狮体长 1.0–1.9 米（含尾），肩高 0.6–0.8 米，体重 29–100 kg，雄性大于雌性。它的毛色从浅棕、灰褐到红褐不等，腹部和口鼻周围颜色较浅，幼兽身上有深色斑点，长大后逐渐消失；四肢修长，后肢尤为强壮，尾巴粗长。\n\n美洲狮分布于北美和南美，从加拿大西南部到智利南部都能见到，栖息环境包括针叶林、热带雨林、草原、荒漠和高山，是美洲分布最广的猫科动物之一。它多在晨昏和夜间单独捕猎，食谱包括鹿、野猪、野兔、啮齿类和家畜，捕猎时以短距离爆发冲刺扑倒猎物。与狮、虎不同，美洲狮的舌骨结构使它不能吼叫，只能发出呼噜、尖叫和嘶嘶声。雌兽妊娠期约 90 天，每胎 1–4 仔。因栖息地破碎和人兽冲突，部分亚种已极度濒危。",
    habitat: "针叶林、热带雨林、草原、荒漠和高山，适应性极强",
    distribution: "北美洲西南部到南美洲南部，是美洲分布最广的猫科动物",
    conservation: "IUCN 无危（LC）",
