    description: "亚洲黑熊体长 1.2–1.9 米，肩高 0.7–1.0 米，体重 60–200 kg，雄性大于雌性。它的全身被毛乌黑发亮，吻部浅棕，胸前有一块醒目的白色月牙或 V 形斑纹；耳朵大而圆，被毛较长，四肢粗壮，爪弯而锋利，善于攀爬。\n\n亚洲黑熊分布于东亚、南亚和东南亚的山地森林，从中国、日本、朝鲜半岛到印度、缅甸，栖息于阔叶林、混交林和亚高山针叶林。它是杂食动物，春季吃嫩芽、树叶，夏季取食浆果、昆虫和蜂蜜，秋季大量进食坚果和果实积累脂肪，也捕食小型兽类。亚洲黑熊多在晨昏活动，善攀爬和游泳，冬季在树洞、岩穴中冬眠，雌熊在冬眠中产仔，每胎 1–3 仔。因熊胆和熊掌贸易，野生种群受到严重威胁，中国将其列为国家二级保护动物。",
