    description: "土狼体长 0.55–0.8 米，尾长 0.2–0.3 米，体重 7–15 kg，外形像小型的鬣狗。它的被毛为浅黄至红褐色，身体两侧和四肢有深色横纹，颈背有可竖起的鬃毛；吻部细尖，牙齿退化，前爪强壮，适合挖掘。\n\n土狼分布于非洲东部和南部的稀树草原和灌丛，栖息于干燥开阔、白蚁资源丰富的地区。它几乎只吃白蚁，一夜间可将长舌伸入成千上万个蚁道舔食白蚁，每天取食量可达数万只；吻部和牙齿已因食性而退化。土狼多为独居或成对活动，多在夜间活动，白天躲在洞穴中。遇敌时会竖起鬃毛、弓背装大，发出嘶吼吓退对手，也会从肛门腺释放气味；它有时会被斑鬣狗捕食。雌兽妊娠期约 90 天，每胎 2–4 仔。土狼种群总体稳定。",
