    summary: "南亚草原上的独角犀，皮肤厚如铠甲并布满颗粒状突起，善游泳，经过严格保护后数量从不足百只回升。",
    description: "印度犀体长 3–3.8 米，肩高 1.6–1.9 米，体重 1600–3200 kg。它全身披着灰褐色厚皮，肩、胁、腿部的皮肤形成巨大褶皱，像披着一层铠甲，皮上密布颗粒状小突起；鼻端长有一只角，最长可超过 30 cm，雌雄都有。\n\n印度犀分布于印度东北部和尼泊尔的草原、湿地与河流冲积平原，栖息于高草丛、沼泽和林缘，善游泳，常在水塘中避暑。它是典型的独居动物，成年雄犀有领地，仅在发情和育幼时短暂相聚。印度犀以草、芦苇和水生植物为食，多在晨昏取食；雌兽妊娠期约 15–16 个月，每胎 1 仔。20 世纪初，印度犀曾因狩猎锐减至不足 100 只，经过印度和尼泊尔数十年的严格保护，种群已恢复到约 4000 头。",
