    summary: "世界上唯一现存的真正野马，鬃毛直立、没有额毛，曾野外灭绝，经人工繁育后在中国新疆等地重新野化。",
    description: "普氏野马体长 2.0–2.8 米，肩高 1.2–1.5 米，体重 200–350 kg。它的体形粗壮，毛色为浅黄至沙褐色，腹部和口鼻周围较浅，鬃毛短而直立，没有家马那样的额毛，尾巴上半部毛短、下半部长；冬季毛被更厚，可抵御严寒。\n\n普氏野马原分布于中亚的草原和荒漠，20 世纪 60 年代野外灭绝，现存个体均源自圈养种群。它与家马有染色体差异：普氏野马有 66 条染色体，家马为 64 条。普氏野马结成 5–15 只的群体，由一匹公马带领多匹母马及幼驹，以针茅、芨芨草等为食，善于长时间奔跑，耐力极强。中国自 1985 年起从欧洲引回个体，在新疆卡拉麦里和甘肃敦煌等地进行野化放归，目前已形成野外繁殖种群。由于遗传多样性低、栖息地有限，其生存仍需持续监测与保护。",
    habitat: "中亚草原与荒漠，偏好干旱开阔、有稀疏水源的草原",
    distribution: "原产于中亚草原，现为中国新疆、甘肃与蒙古的野化放归地",
