    summary: "青藏高原特有的野生驴，体形健壮、毛色红棕、腹部雪白，奔跑能力强，常与越野车赛跑，是国家一级保护动物。",
    description: "藏野驴体长 1.8–2.2 米，肩高 1.3–1.4 米，体重 250–400 kg，是青藏高原体型最大的野生有蹄类之一。它的被毛为红棕至沙褐色，腹部和四肢内侧雪白，脊背有一条深色纵纹，四肢修长，蹄小而坚实，耳朵长而直立。\n\n藏野驴分布于青藏高原及其周边的高寒草原、荒漠和山地，从中国西藏、青海、新疆、甘肃到印度、尼泊尔、不丹的边境地区，栖息于海拔 2700–5400 米的区域。它结成 5–50 只的群体，以针茅、苔草等为食，多在晨昏取食和饮水，善于长时间奔跑，时速可达 60–70 km/h，有时会与汽车并排奔跑。雄驴在繁殖季争夺配偶，雌兽妊娠期约 11–12 个月，每胎 1 仔。由于栖息地相对完整和严格保护，藏野驴种群总体稳定，中国将其列为国家一级保护动物。",
