    description: "獐体长 0.9–1.1 米，肩高 0.5–0.6 米，体重 9–18 kg，是体型较小的鹿类。它的毛色为黄褐至灰黄色，腹部和喉部较浅，尾巴极短；雌雄都不长角，雄鹿的上犬齿发达，向下外露形成獠牙状，用于争斗和展示。\n\n獐分布于中国长江流域及东南沿海的湿地、丘陵灌丛和河岸草地，朝鲜半岛也有分布，是中国东部湿地的重要鹿类。它多在晨昏活动，独居或成对，以草、树叶、嫩枝和水生植物为食，善游泳，受惊时常跳入水中逃走。繁殖季雄鹿用獠牙争夺配偶；雌兽妊娠期约 6–7 个月，每胎 1–2 仔。由于湿地开发、非法捕猎和栖息地破碎，獐的野生种群明显下降，被列为易危，中国将其列为国家二级保护动物。",
