    summary: "现存最大的齿鲸，头部长方体状、占体长三分之一，能潜入两千米深海捕食大王乌贼，体内可形成龙涎香。",
    description: "抹香鲸体长 11–18 米，体重 15–50 吨，雄性明显大于雌性，是现存最大的齿鲸。它的头部巨大呈长方体状，约占体长的三分之一，内含鲸脑油器官；身体皮肤多皱褶，呈深灰至黑褐色，下颌窄小，长有一排圆锥形牙齿，背鳍小而圆。\n\n抹香鲸分布于全球各大洋的深水海域，从极地到热带都能见到，常结群活动。它是潜水能力最强的鲸类之一，可下潜到 2000 米以上，一次闭气可达 90 分钟，主要捕食深海的大王乌贼、章鱼和鱼类，潜水时常发出响亮的咔嗒声用于回声定位。抹香鲸的肠道分泌物可形成名贵的龙涎香，历史上曾因此被大量捕杀。雌鲸妊娠期约 14–16 个月，每胎 1 仔。目前全球种群估计有数十万头，被列为易危。",
    habitat: "全球各大洋的深水海域，从极地到热带均有分布",
