    description: "灰鲸体长 12–15 米，体重 15–40 吨，雌性略大于雄性。它的身体粗壮呈纺锤形，皮肤为灰色并布满白色斑驳和藤壶、鲸虱留下的痕迹，没有背鳍，背部只有一列小突起；头部较短，鲸须短而粗糙。\n\n灰鲸分布于北太平洋，分为东、西两个种群：东太平洋种群在墨西哥下加利福尼亚的潟湖繁殖，夏季到白令海和北极海域觅食；西太平洋种群则沿亚洲东岸迁徙，数量极少。它是迁徙距离最长的哺乳动物之一，每年往返可达约 2 万公里，沿海岸线迁徙，常贴近岸边游动。灰鲸主要在海底侧卧吸食底栖甲壳类，会用嘴翻起泥沙过滤食物；雌鲸妊娠期约 13–14 个月，每胎 1 仔。东太平洋种群在保护后恢复良好，西太平洋种群仍极度濒危。",
