    description: "宽吻海豚体长 2.0–3.9 米，体重 150–650 kg，雄性略大于雌性。它的身体流线型，背鳍高而弯，吻部短粗如瓶口，因此也称瓶鼻海豚；体色为深灰至灰褐色，腹部较浅，眼周有深色斑纹，嘴角自然上翘，看起来像在微笑。\n\n宽吻海豚分布于全球各大洋的温带和热带海域，包括近岸浅海和远洋，是分布最广的海豚之一。它结成 5–30 只的群体，群体结构复杂，个体有各自的“签名哨声”；智力高，善于学习，会用回声定位探测鱼群，部分个体还会用海绵保护吻部在海底觅食。宽吻海豚以鱼类、乌贼和甲壳类为食，常与人类船只互动，也是海洋馆中最常见的海豚。雌鲸妊娠期约 12 个月，每胎 1 仔。全球种群总体稳定，但部分近岸种群受污染和渔业误捕影响。",
