    description: "海象体长 2.2–3.6 米，体重 400–1700 kg，雄性大于雌性，是体型最大的鳍足类之一。它的皮肤厚而粗糙，呈粉褐至黄褐色，成年雄兽颈部和肩部皮肤布满结节；上犬齿长成两根长长的獠牙，雄兽獠牙可达 1 米，雌兽稍短。\n\n海象分布于北极和亚北极海域，从加拿大、格陵兰、斯瓦尔巴到俄罗斯北部和阿拉斯加，栖息于浅海、浮冰和海岸。它以海底的蛤蜊、螺类等贝类为食，用胡须感知泥沙中的贝类，再用嘴唇和舌头把肉吸出；獠牙用于攀爬冰面、防御和展示。海象结成数十至数千只的大群，在冰上或岸上休息，雄性通过獠牙和声音争夺地位。雌兽妊娠期约 15–16 个月，每胎 1 仔。气候变暖导致海冰减少，海象的休息平台和觅食区受到威胁，被列为易危。",
