    description: "大食蚁兽体长 1.8–2.2 米（含尾），体重 25–45 kg。它的头部细长呈管状，吻端很小，嘴里没有牙齿；舌头细长可伸到 60 cm，表面覆有黏液；身体覆粗糙长毛，体侧有黑色斜纹，前肢强壮，前爪锋利，尾巴蓬松如帚。\n\n大食蚁兽分布于中美洲和南美洲，从墨西哥南部到阿根廷北部，栖息于热带雨林、稀树草原、沼泽和疏林。它靠嗅觉寻找蚂蚁和白蚁巢，用前爪扒开蚁巢后迅速伸缩长舌舔食昆虫，一天可造访数十个蚁巢，但不会把一个蚁巢吃空。大食蚁兽多为独居，晨昏和夜间活动，走路时前掌背屈着地以保护爪尖，遇险时会用后肢站立、挥动前爪防御。雌兽妊娠期约 190 天，每胎 1 仔，幼仔常骑在母兽背上。由于栖息地丧失和交通事故，大食蚁兽被列为易危。",
