    description: "三趾树懒体长 0.4–0.75 米，体重 3–5 kg。它的身体圆而扁，四肢细长，前肢和后肢各有三趾，趾端有长而弯曲的钩爪，可以牢牢挂住树枝；被毛为灰褐至棕褐色，毛干上有沟槽，常附生绿藻，使它看起来偏绿；面部有深色眼纹。\n\n三趾树懒分布于中美洲和南美洲北部的热带雨林，栖息于树冠层，几乎终生在树上活动。它行动极慢，每天睡 15–20 小时，主食树叶、嫩芽和果实，消化过程缓慢，一周左右才下树到地面排泄一次。树懒的毛上共生着绿藻和蛾类，形成独特的小生态；游泳时反而比在地面行走快。雌兽妊娠期约 6 个月，每胎 1 仔，幼仔会抓住母兽胸部随行。由于雨林砍伐和道路切割，部分种群受到威胁，但整体被列为无危。",
