    description: "九带犰狳体长 0.35–0.6 米，尾长 0.25–0.45 米，体重 3–6 kg。它的背部和头部覆有骨质甲片，肩部和臀部的甲片固定，中间有 9 条可活动的带状甲片，使它能够蜷曲；吻部尖长，耳朵大，四肢短，前爪强壮，适合挖掘。\n\n九带犰狳分布于美洲，从美国南部经中美洲到南美洲北部，栖息于森林、灌丛、草原和农田，适应力强。它多在夜间活动，靠嗅觉寻找昆虫、蚯蚓、蜗牛和小型脊椎动物，也会挖洞捕食；受惊时会突然向上跳起，这反而常使它被汽车撞到。九带犰狳善于挖洞和憋气，能屏住呼吸在水下或松土中活动数分钟。雌兽妊娠期约 4 个月，一胎通常产 4 只同卵幼仔。九带犰狳是研究麻风病的特殊动物模型，种群总体稳定。",
