    description: "白颊长臂猿体长 0.45–0.6 米，体重 5–8 kg，没有尾巴。成年雄猿通体黑色，面颊两侧有醒目的白色毛；雌猿大部分为金黄色，头顶有黑色冠斑，两者毛色差异明显。它的手臂极长，手掌长而弯曲，适合在树冠层用双臂摆荡前进。\n\n白颊长臂猿分布于中国云南南部、老挝、越南和泰国的热带雨林，栖息于常绿阔叶林和山地雨林。它是树冠层的“臂行者”，双臂摆荡前进，一次可跨越数米，速度极快；多以家庭群活动，一夫一妻，早晨雌雄会合唱，用歌声宣告领地并加强配偶联系。它以果实、嫩叶、花芽和昆虫为食。雌兽妊娠期约 7–8 个月，每胎 1 仔。由于森林砍伐和非法捕猎，白颊长臂猿被列为极危，中国境内野生种群极为稀少，被列为国家一级保护动物。",
