    description: "黑冠猕猴体长 0.45–0.6 米，体重 5–10 kg，尾极短。它全身覆黑色短毛，头顶的毛向上竖起形成尖冠，因此得名；面部裸露呈黑色，臀部皮肤为醒目的粉红色。雄性的犬齿较大，面部表情丰富，常通过咧嘴展示牙齿进行交流。\n\n黑冠猕猴是印度尼西亚苏拉威西岛北部的特有种，栖息于热带雨林、次生林和红树林。它以果实、树叶、花芽和昆虫为食，结成 5–25 只的群体，由成年雄性担任首领，群体成员通过理毛和面部表情维持关系。黑冠猕猴每天在树冠和林下层活动，夜间在树上休息，活动范围较大。雌性妊娠期约 170 天，每胎 1 仔。由于当地人将其视为食物而大量捕猎，加上森林砍伐，黑冠猕猴种群急剧下降，被列为极危，是世界上最濒危的灵长类之一。",
