    description: "阿拉伯狒狒体长 0.6–0.8 米，体重 10–30 kg，雄性明显大于雌性。雄性肩部、颈部和背部覆银色至灰白色的长毛，像披着一件斗篷；面部裸露呈粉色，吻部较长，雌性毛色较暗淡。雄性的犬齿发达，常用来威吓对手。\n\n阿拉伯狒狒分布于非洲之角（埃塞俄比亚、索马里、苏丹）和阿拉伯半岛西南部，栖息于半荒漠、稀树草原和岩石山地。它白天在地面活动，以草、种子、果实、根茎和昆虫为食，夜间在岩壁上休息。群体结构复杂：一只雄性统领 2–6 只雌性组成“家族”，多个家族又结成数十至数百只的族群，雄性会通过控制雌性和相互结盟维持地位。雌性妊娠期约 170–180 天，每胎 1 仔。阿拉伯狒狒适应力强，种群总体稳定。",
