    description: "山魈体长 0.55–0.8 米，体重 13–35 kg，雄性明显大于雌性，是体型最大的猴类。雄性面部色彩极为醒目：鼻梁和眉脊呈蓝色，鼻端和嘴唇为鲜红色，面颊两侧有黄白色胡须；臀部皮肤呈蓝、紫、红色相间。全身毛色为深橄榄绿至棕褐色。\n\n山魈分布于非洲中部的加蓬、喀麦隆、赤道几内亚和刚果，栖息于热带雨林和河谷森林，是地面活动为主的猴类。它以果实、种子、树叶、根茎和小型动物为食，结成 20–100 只的大群，雄性之间通过展示面部色彩、点头和战斗维持等级，一雄多雌。山魈多在白天活动，夜间爬到树上休息，群体行动范围大。雌性妊娠期约 170–190 天，每胎 1 仔。由于森林砍伐和丛林肉贸易，山魈数量下降，被列为易危，是非洲最受关注的灵长类之一。",
