    description: "白眉长臂猿体长 0.4–0.6 米，体重 5–8 kg，没有尾巴，是体型较小的长臂猿。雄性通体黑色，眉部有一条明显的白色带纹，因此得名；雌性为黄褐至灰白色，面部有浅色环纹。前肢明显长于后肢，双手呈钩状，适合在树冠层摆荡。\n\n白眉长臂猿分布于孟加拉国、印度东北部、缅甸和中国云南西部的热带雨林和山地常绿林，是树冠层的臂行高手，常在树间摆荡跃过数米距离。它以果实、嫩叶、花芽和小型动物为食，过一夫一妻的家庭群生活，早晨雄性和雌性会合唱二重唱，用歌声宣告领地并加强配偶关系。雌性妊娠期约 7 个月，每胎 1 仔，幼仔约 2 岁才独立。由于森林砍伐和非法捕猎，白眉长臂猿数量持续下降，被列为濒危。",
