    description: "鼬獾体长 0.33–0.43 米，尾长 0.15–0.2 米，体重 0.5–1.8 kg。它的体形细长，被毛为灰褐至黑褐色，面部有白色和黑色相间的面罩状斑纹，头顶有浅色纵纹；吻部突出、鼻端裸露，前爪发达，适合挖掘。\n\n鼬獾分布于中国南方、中南半岛和印度东北部的丘陵、山地森林、灌丛和农田附近，适应力较强。它多在夜间单独活动，白天在洞穴或石缝中休息，用鼻端拱土和落叶层寻找蚯蚓、昆虫、蜗牛、小型脊椎动物和果实。鼬獾性情较凶猛，遇敌时会从肛腺释放臭气。雌性妊娠期约 60–70 天，每胎 2–3 仔。鼬獾在中国南方较为常见，目前被列为无危，中国将其列入“三有”保护动物名录。",
    habitat: "丘陵、山地森林、灌丛与农田附近",
