    description: "美洲水貂体长 0.3–0.45 米，尾长 0.15–0.25 米，体重 0.5–1.5 kg，雄性大于雌性。它的身体细长，被毛为深褐至黑褐色，腹部有时带白斑；头部扁平，耳朵小，四肢短而有力，趾间有蹼，尾巴粗壮，适合在水中游泳。\n\n美洲水貂原产于北美洲，栖息于河流、湖泊、沼泽和海岸附近的林地。它是半水生猎手，善游泳和潜水，以鱼类、蛙类、甲壳类、鼠类、鸟类和鸟卵为食，多在夜间活动，白天在洞穴中休息。美洲水貂的皮毛防水保暖，是重要的毛皮兽，因此被世界各地大量饲养，逃逸个体在欧洲等地形成入侵种群，对当地水鸟和鱼类造成影响。雌性妊娠期约 40–75 天，每胎 3–6 仔。其北美野生种群总体稳定，被列为无危。",
