    description: "羚牛体长 1.7–2.2 米，肩高 1.1–1.3 米，体重 250–400 kg，雄性大于雌性。它的体形粗壮，毛色有金黄、浅黄和灰褐等类型，毛长而蓬松；面部似羊，角从头顶向外后方弯曲，吻部宽大，四肢粗壮，蹄大而宽，尾巴短。\n\n羚牛分布于中国西南的四川、陕西、甘肃、云南、西藏以及印度、缅甸和不丹的山地，栖息于海拔 1500–4500 米的高山森林、草甸和岩壁。它结成几只至数十只的群体，以草、树叶、嫩枝和竹叶为食，夏季上移到高山草甸，冬季下移，性情较凶猛，受惊时会成群冲撞。因外形集合了牛、羊、羚等多种动物的特征，被称为“六不像”。雌性妊娠期约 8–9 个月，每胎 1 仔。由于栖息地破碎和捕猎，羚牛被列为易危，中国将其列为国家一级保护动物。",
