    description: "细纹斑马体长 2.5–2.75 米，肩高 1.45–1.6 米，体重 350–450 kg，是现存体型最大的斑马。它的条纹比其他斑马更细更密，背部条纹延伸到臀部，腹部为白色；耳朵大而圆，四肢细长，蹄窄，适合在干旱草原上长途迁徙。\n\n细纹斑马分布于肯尼亚北部和埃塞俄比亚的干旱草原、灌丛和半荒漠，是非洲之角的特有种群。它以草和灌木为食，与其它斑马不同，成年雄性占有较大领地并独占水源附近的交配权，雌性带着幼驹在领地间自由活动。细纹斑马能长时间不饮水，可在干旱环境中迁徙寻找草场。雌性妊娠期约 13 个月，每胎 1 仔。由于盗猎、栖息地退化和水源竞争，细纹斑马数量从数万只锐减至约 2000–3000 只，被列为濒危。",
