    description: "真海豚体长 1.7–2.4 米，体重 70–135 kg，雄性略大。它的背部深灰至黑色，腹部白色，身体两侧有一条黄褐色或浅灰色的沙漏状斑纹，背鳍三角形、略后弯，喙细长，上下颌各有约 40–50 枚小而尖的牙齿。\n\n真海豚广泛分布于全球温带和热带海域，包括大西洋、太平洋和印度洋，在中国东海、黄海和南海也有记录。它喜欢在表层温暖水域活动，常结成数十至数千只的大群，游泳速度快，经常跃出水面。它以小型鱼类、乌贼和虾类为食，群体协作围捕鱼群。雌性妊娠期约 10–11 个月，每胎 1 仔，寿命约 25–30 年。真海豚整体数量较多，被列为无危，但渔网误捕是主要威胁。",
    habitat: "温带和热带海域的表层水域，包括近岸和远洋",
