    description: "海獭体长 1.2–1.5 米，体重 15–45 kg，雄性略大。它的身体细长，头部小而圆，后肢特化为宽大的鳍足，尾巴扁平如桨；毛皮呈深褐色，密度极高，每平方厘米约有 10 万根毛发，能在冷海中保持体温。\n\n海獭分布于北太平洋沿岸，从日本北部、俄罗斯远东到美国阿拉斯加和加利福尼亚，生活在海藻林和近岸浅海。它以海胆、贝类、螃蟹和鱼类为食，常仰浮在水面，把石头放在胸前敲开海胆，是少数会使用工具的动物。海獭每天需进食相当于体重 25% 的食物。雌性妊娠期约 6 个月，每胎 1 仔，寿命约 15–20 年。由于 18–19 世纪的毛皮贸易，海獭数量锐减，目前被列为濒危，保护工作使部分种群有所恢复。",
