    description: "欧洲鼹鼠体长 13–16 厘米，体重 65–120 克。它的身体呈圆柱形，覆盖黑色至深灰色的短毛，毛皮柔软、没有方向性，在隧道中进退都不会被毛阻碍；前肢粗短，手掌宽大如铲，向外翻转，适合挖掘；眼睛极小，藏在皮下，视力很差，嗅觉和触觉发达。\n\n欧洲鼹鼠分布于欧洲大部分地区，栖息在草地、农田、森林和花园的土壤中，一生几乎都在地下隧道里度过。它挖掘复杂的浅层和深层隧道，捕食蚯蚓、昆虫幼虫和蜗牛，食量很大，每天要吃下接近体重一半的食物。鼹鼠在地面留下成堆的土丘，是花园中常见的痕迹。雌性妊娠期约 4–5 周，每胎 3–5 仔，寿命约 3–5 年。欧洲鼹鼠被列为无危。",
