    description: "短尾矮袋鼠体长 40–54 厘米，尾长 25–30 厘米，体重 2.5–5 千克。它的身体矮壮，脸圆、耳朵短，尾巴较短，毛色为灰褐至红棕色，看起来像在微笑，因此被称为“世界上最快乐的动物”。\n\n短尾矮袋鼠分布于澳大利亚西南部，主要种群在罗特尼斯岛和附近大陆的灌丛中。它夜行性，以树叶、草、种子和茎为食，会反刍食物，能在缺水的环境中从植物中获取水分。短尾矮袋鼠性情温和，允许人类靠近，是罗特尼斯岛著名的旅游吸引物。雌性妊娠期约 27 天，幼仔在育儿袋中生活约 6 个月，寿命约 10 年。由于栖息地破坏、狐狸和猫的捕食，短尾矮袋鼠被列为易危。",
    habitat: "澳大利亚西南部的灌丛、林地和岛屿",
    distribution: "澳大利亚西南部，主要种群在罗特尼斯岛",
