    description: "豚鼠体形圆润，成年体长 20–30 厘米，体重 0.7–1.2 千克，四肢短小，没有尾巴，耳小而圆。毛被因品系不同而差异极大：有短毛、逆毛、长毛等类型，颜色包括白、黑、棕、橙及多色花斑。头部较大，吻部短钝，上唇裂开，门齿终生生长；脚掌裸出，前足四趾、后足三趾。\n\n豚鼠由南美洲安第斯山区的野豚鼠驯化而来，驯化历史约五千年，当地原住民早已将其作为肉食与仪式用动物。它社会性强，喜群居，靠短促的“啾啾”叫声和身体接触交流，受到惊吓时会僵住或急速逃窜。食性为严格的草食，需要不断进食纤维并自行合成维生素 C。母鼠孕期约 59–72 天，每胎 1–4 仔，幼仔出生即睁眼、有毛并能行走。如今豚鼠广泛作为宠物、实验动物与教学动物饲养。",
