    description: "鼩鼱体形细长，成年体长 6–9 厘米，尾长 3–5 厘米，体重仅 5–14 克，是欧亚大陆最常见的小型食虫类之一。吻部尖长而灵活，眼小，耳壳不明显，毛被短而密，背毛呈棕褐或暗灰色，腹面浅灰，齿尖呈红色，这是铁质沉积在牙釉质中的结果。它四肢短小，五指有爪，常发出尖锐的吱吱声。\n\n鼩鼱栖息于森林、草地、农田、沼泽与花园的落叶层和草丛中，昼夜均活动，靠嗅觉与触觉在缝隙里搜寻昆虫、蜘蛛、蚯蚓、蜗牛和小型脊椎动物。它的代谢率极高，每天需进食相当于体重 80%–90% 的食物，饥饿数小时即可能死亡，因此几乎整日奔波觅食。唾液腺分泌物具轻微毒性，可让较大的昆虫或小鼠行动迟缓。每年繁殖 2–3 胎，孕期约 19–21 天，每胎 5–8 仔。冬季不冬眠，会收缩身体与骨骼以减少消耗。",
