    description: "棕蝠是体型较大的欧洲蝙蝠，前臂长 45–57 毫米，体重 15–35 克，翼展约 32–38 厘米。毛被浓密，背毛深棕至烟褐色，腹面较浅，毛基深、毛尖浅，呈现轻微霜状光泽；耳短而宽，耳屏略呈蘑菇形，吻部宽钝，面部裸皮深褐。翼膜深褐色，尾膜宽大，飞行时显得沉稳有力。\n\n棕蝠栖息于城镇与乡村的屋顶、墙缝、阁楼、树洞和岩缝，是典型的“屋栖蝙蝠”，常与人类建筑共存。黄昏后起飞，沿林缘、河岸、街道和庭院低空巡飞，捕食甲虫、蛾类、蚊蚋等飞行昆虫，飞行速度不快但机动灵活，靠回声定位在复杂环境中穿行。夏季集群育幼，雌兽在 6–7 月产仔，通常每胎一仔，幼蝠约一个月后能飞。冬季在洞穴、地下室或建筑缝隙中冬眠。它在欧洲部分地区携带狂犬病相关病毒，接触需谨慎。",
    habitat: "城镇建筑屋顶、阁楼、墙缝、树洞与岩缝，觅食于林缘与水域上空",
