    description: "马来穿山甲体形修长，成年体长 40–65 厘米，尾长 35–58 厘米，体重 3–10 千克。全身除吻部、腹部和四肢内侧外覆盖角质鳞片，鳞片呈灰褐至深褐色，边缘锐利，由角蛋白构成，与指甲成分相同。头小吻尖，无齿，舌极长且能伸出体外，唾液黏稠，可黏附蚁类；四肢粗壮，前爪长而弯，善掘洞与攀爬，尾具缠绕性。\n\n它们栖息于东南亚的热带雨林、季雨林和次生林，独居，多在夜间活动，白天躲在自挖的洞穴或树洞中。嗅觉灵敏，能循气味找到白蚁巢与蚁巢，用前爪掘开巢壁后伸舌舔食，一顿可吃掉数千只蚁。遇险时蜷成一团，用鳞片护住腹部，连虎豹也难以下口。每年繁殖一胎，孕期约 5–6 个月，每胎一仔。因鳞片被当作药材、肉被视为野味，它长期遭受大规模盗猎和走私，野外种群急剧下降。",
    habitat: "热带雨林、季雨林、次生林与农林交界的林地",
    distribution: "缅甸、泰国、越南、马来西亚、印度尼西亚苏门答腊与爪哇、婆罗洲",
    conservation: "IUCN 极危（CR）；CITES 附录Ⅰ；中国国家一级保护动物",
