    description: "树鼩体形纤细，成年体长 12–21 厘米，尾长 14–20 厘米，体重 50–180 克。吻部尖长，眼大而圆，耳短圆，毛被柔软，背毛橄榄褐至灰褐色，腹面浅黄或灰白，肩侧常有一条浅色纵纹；尾毛蓬松，略长于身体。四肢细长，前爪长而尖锐，能在树干和枝条间灵活攀爬，但不善长距离跳跃。\n\n树鼩分布于中国西南至东南亚的常绿阔叶林、竹林、灌丛与农地边缘，昼夜均活动，以昆虫、果实、种子、嫩叶和小型脊椎动物为食，常在树根、倒木和石缝间搜寻。它多单独或成对活动，领域性较强，会用胸腹腺体分泌物在树枝上标记。繁殖期较长，孕期约 40–50 天，每胎 1–4 仔。树鼩在分类上与灵长类亲缘较近，是研究肝炎、视觉与脑科学的常用实验动物，因此也被大量人工繁育。",
