    description: "蹄兔体形粗壮，成年体长 40–55 厘米，体重 2–4.5 千克，几乎没有尾巴。毛被厚实，背毛灰褐至黄褐色，腹部浅黄，背部中央常有一块深色斑，斑下有一组腺体，受惊时会竖起毛露出颜色。头部短圆，耳小而圆，上唇裂开；四肢短粗，前足四趾、后足三趾，趾端有蹄状甲，脚掌有弹性肉垫，能像吸盘一样吸附在陡峭岩壁上。\n\n蹄兔栖息于非洲与中东的岩石山地、峡谷和花岗岩孤丘，白天成群在岩石上晒太阳，清晨集体鸣叫，声音尖锐如哨。它们以草、树叶、嫩枝与树皮为食，能长时间不饮水，靠食物中的水分与浓缩尿液节约用水。群体由十余只至数十只组成，有哨兵在制高点警戒，发现猛禽或豹时发出不同警报声。每年繁殖一胎，孕期约 7–8 个月，每胎 1–4 仔。分子研究显示，蹄兔与大象、海牛同属非洲兽总目，亲缘关系出人意料地近。",
