    description: "北美豪猪体形粗壮，成年体长 60–90 厘米，尾长 15–30 厘米，体重 3.5–18 千克，是北美体型第二大的啮齿动物。全身除面部、腹部和四肢内侧外覆盖棘刺，背部与尾部刺最长，约 8 厘米，刺尖带细密倒钩，一旦刺入皮肤会因体温与肌肉运动越陷越深，且刺上可能带有抗菌油脂。毛色黑褐，刺的基部白色、尖端黑色，形成斑驳外观。\n\n它们栖息于北美北部的针叶林与混交林，多在树上活动，是出色的攀爬者，以树皮、嫩枝、针叶、芽和落叶为食，冬季会长时间停留在同一棵树上啃食树皮，留下明显痕迹。北美豪猪独居，夜间活动，遇敌时不逃跑而是背对对手、竖起棘刺并甩动尾巴，让捕食者满脸是刺。每年秋季繁殖，孕期约 7 个月，每胎一仔，幼仔出生时棘刺已软，数小时后变硬。它对树皮的大量啃食会影响林木生长，被视为林业害兽。",
