    description: "黑尾土拨鼠体形圆胖，成年体长 35–43 厘米，尾长 7–10 厘米，体重 0.7–1.4 千克，雄性略大。毛色沙黄至棕褐，腹部浅白，尾端有一撮黑色长毛，是其与白尾土拨鼠区分的主要特征。头圆耳小，眼位于头侧，视野开阔；前爪发达，用于挖掘与修整洞口。\n\n它们栖息于北美大平原的短草草原与荒漠草原，营大型群体生活，家族由一只雄性、数只雌性及幼仔组成，多个家族连成“城镇”，洞道纵横相连，洞口周围堆出环形土丘防止雨水倒灌。白天活动，以草与种子为食，冬眠但不深睡，冬季仍会出洞。发现天敌时，哨兵会直立发出不同的叫声，分别对应鹰、獾、郊狼乃至人类，同伴据此决定躲避或警戒。每年繁殖一胎，孕期约 28–32 天，每胎 3–5 仔。由于被视为牲畜竞争者而被大规模毒杀，其分布区已大幅缩减。",
