    description: "岩松鼠体形中等，成年体长 20–25 厘米，尾长 12–16 厘米，体重 200–350 克。毛被粗糙，背毛灰褐至黄褐色，毛尖带黑色，腹面浅灰或污白，眼周有一圈浅色毛，耳壳小而圆，不似树松鼠那样长出长毛簇；尾毛蓬松但不像其他松鼠那样向背上卷曲，故有“扫尾子”之称。\n\n它们是中国北方的特有种，分布于华北、西北的山地与丘陵，栖息于岩石裸露的沟谷、石堰、梯田边缘和灌丛，常在岩缝、石堆下筑巢，也在土坡挖洞。白天活动，以坚果、种子、浆果和农作物为食，秋季会把核桃、橡子等坚果搬到石缝中分散储藏，供冬季取食。它们多在岩面与地面活动，攀爬能力不及树松鼠，遇险时迅速钻入石缝并发出短促尖叫。每年繁殖 1–2 胎，孕期约 30 天，每胎 3–6 仔。因取食农林果实，在部分地区被视为害兽。",
