    description: "指猴体长 30–40 cm，尾长 55–60 cm，体重约 2–3 kg。全身覆粗硬的深褐至黑色长毛，头部圆大，耳朵大而裸露，眼睛橙黄，门齿像啮齿类一样终生生长；第三指极度细长，可灵活伸入树洞钩取食物，是最具辨识度的特征。\n\n它们仅分布于马达加斯加东部的热带雨林和部分落叶林，夜间在树冠层单独活动。觅食时先用中指有节奏地敲击树皮，凭回声判断蛀洞内是否有幼虫，再咬开树皮用长指钩出；也吃果实、花蜜、种子和真菌。每胎一仔，妊娠期约 160 天。由于栖息地破坏和当地将其视为不祥之物的捕杀，野生种群估计仅数千只，被列为濒危物种。",
